478	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
479	    @Override
480	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
481	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
482	        if (currentOwner == null) {
483	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
484	        }
485	        currentOwner.setAddress(ownerFieldsDto.getAddress());
486	        currentOwner.setCity(ownerFieldsDto.getCity());
487	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
488	        currentOwner.setLastName(ownerFieldsDto.getLastName());
489	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
490	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
491	        this.clinicService.saveOwner(currentOwner);
492	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
493	    }
