526	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
527	    @Override
528	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
529	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
530	        if (currentOwner != null) {
531	            Pet currentPet = this.clinicService.findPetById(petId);
532	            if (currentPet != null) {
533	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
534	                currentPet.setName(petFieldsDto.getName());
535	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
536	                this.clinicService.savePet(currentPet);
537	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
538	            }
539	        }
540	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
541	    }
