28	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
29	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
30	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
31	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
32	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
33	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
34	    @Mapping(target = "locality", expression = "java(locality(owner))")
35	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
36	    OwnerDto toOwnerDto(Owner owner);
37	
38	    /**
39	     * Derives an owner's preferred contact channel: {@code "EMAIL"} when the owner has a non-blank
40	     * email, otherwise {@code "PHONE"}.
41	     *
42	     * @param owner the owner to derive the contact preference for
43	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
44	     */
45	    default String contactPreference(Owner owner) {
46	        String email = owner.getEmail();
47	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
48	    }
49	
50	    /**
51	     * Derives an owner's locality, preferring the postcode over the city. The postcode is looked up
52	     * against the canonical region ranges first ({@code NSW 2000-2099}, {@code VIC 3000-3099},
53	     * {@code QLD 4000-4099}); only when the postcode is absent or falls in no known range does the
54	     * derivation fall back to the fixed city-to-region table ({@code Sydney->NSW},
55	     * {@code Melbourne->VIC}, {@code Brisbane->QLD}). This returns the same region for known cities
56	     * but disambiguates cities that share a name. The result is {@code "UNKNOWN"} when neither the
57	     * postcode nor the city resolves to a region.
58	     *
59	     * @param owner the owner to derive the locality for
60	     * @return the canonical region string, or {@code "UNKNOWN"}
61	     */
62	    default String locality(Owner owner) {
63	        String region = regionFromPostcode(owner.getPostcode());
64	        if (region != null) {
65	            return region;
66	        }
67	        return regionFromCity(owner.getCity());
68	    }
69	
70	    /**
71	     * Looks up the canonical region for a postcode by its range ({@code NSW 2000-2099},
72	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}).
73	     *
74	     * @param postcode the owner's postcode, may be {@code null}
75	     * @return the region, or {@code null} when the postcode is absent, non-numeric or in no range
76	     */
77	    private String regionFromPostcode(String postcode) {
78	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
79	            return null;
80	        }
81	        int value = Integer.parseInt(postcode);
82	        if (value >= 2000 && value <= 2099) {
83	            return "NSW";
84	        }
85	        if (value >= 3000 && value <= 3099) {
86	            return "VIC";
87	        }
88	        if (value >= 4000 && value <= 4099) {
89	            return "QLD";
90	        }
91	        return null;
92	    }
93	
94	    /**
95	     * Looks up the canonical region for a city using the fixed city-to-region table.
96	     *
97	     * @param city the owner's city, may be {@code null}
98	     * @return the region, or {@code "UNKNOWN"} when the city is absent or not in the table
99	     */
100	    private String regionFromCity(String city) {
101	        if (city == null) {
102	            return "UNKNOWN";
103	        }
104	        return switch (city) {
105	            case "Sydney" -> "NSW";
106	            case "Melbourne" -> "VIC";
107	            case "Brisbane" -> "QLD";
108	            default -> "UNKNOWN";
109	        };
110	    }
111	
112	    /**
113	     * Derives an owner's numeric membership level, fixed at creation. Starts at {@code 1}, plus
114	     * {@code 1} when an email is present (non-blank), plus {@code 1} when the owner's namesake count
115	     * is {@code 0}, capped at {@code 3} (level {@code 4} is reserved for tenure).
116	     *
117	     * @param owner the owner to derive the membership level for
118	     * @return the membership level, between {@code 1} and {@code 3}
119	     */
120	    default Integer membershipLevel(Owner owner) {
121	        int level = 1;
122	        String email = owner.getEmail();
123	        if (email != null && !email.isBlank()) {
124	            level++;
125	        }
126	        Integer namesakeCount = owner.getNamesakeCount();
127	        if (namesakeCount != null && namesakeCount == 0) {
128	            level++;
129	        }
130	        return Math.min(level, 3);
131	    }
132	
133	    /**
134	     * Derives an owner's membership number, formatted {@code <customerCode>-M<YY>} where
135	     * {@code <customerCode>} is the owner's customer code and {@code YY} is the last two digits
136	     * (zero-padded) of the owner's registration date year (e.g. {@code LON-SMI-0007-M26}).
137	     *
138	     * @param owner the owner to derive the membership number for
139	     * @return the formatted membership number
140	     */
141	    default String membershipNumber(Owner owner) {
142	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
143	        return owner.getCustomerCode() + "-M" + yy;
144	    }
145	
146	    /**
147	     * Derives an owner's household identifier: a stable value shared by every owner with the same
148	     * last name and address (compared case-insensitively with collapsed whitespace). Because it is
149	     * derived deterministically from those fields, owners created via the {@code sharesHousehold}
150	     * flag - which by definition have a matching last name and address - receive the same value.
151	     *
152	     * @param owner the owner to derive the household identifier for
153	     * @return a {@code HH-} prefixed identifier, never blank
154	     */
155	    default String householdId(Owner owner) {
156	        String key = normalizeHouseholdField(owner.getLastName()) + ' '
157	            + normalizeHouseholdField(owner.getAddress());
158	        try {
159	            byte[] digest = MessageDigest.getInstance("SHA-256")
160	                .digest(key.getBytes(StandardCharsets.UTF_8));
161	            StringBuilder sb = new StringBuilder("HH-");
162	            for (int i = 0; i < 6; i++) {
163	                sb.append(String.format("%02X", digest[i]));
164	            }
165	            return sb.toString();
166	        }
167	        catch (NoSuchAlgorithmException ex) {
168	            throw new IllegalStateException("SHA-256 not available", ex);
169	        }
170	    }
171	
172	    /**
173	     * Derives an owner's identity key, into which all duplicate detection is consolidated. The key
174	     * is {@code <normalizedTelephone>|<email or empty>|<householdId>}: the owner's (already E.164
175	     * normalized) telephone, its (already lower-cased) email or the empty string when none is held,
176	     * and its {@link #householdId(Owner) household id}. Two owners are duplicates only when their
177	     * whole identity keys are equal; because the telephone is part of the key, household members with
178	     * different telephones have different keys.
179	     *
180	     * @param owner the owner to derive the identity key for
181	     * @return the {@code telephone|email|householdId} identity key
182	     */
183	    default String identityKey(Owner owner) {
184	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
185	        String email = owner.getEmail() == null ? "" : owner.getEmail();
186	        return telephone + '|' + email + '|' + householdId(owner);
187	    }
188	
189	    /**
190	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields can
191	     * be compared case-insensitively with collapsed whitespace. A {@code null} value normalizes to
192	     * the empty string. Mirrors the normalization used when enforcing the household rule on create.
193	     *
194	     * <p>Declared {@code private} so MapStruct does not treat it as an implicit String-to-String
195	     * conversion and apply it to unrelated String properties (last name, address, ...).
196	     */
197	    private String normalizeHouseholdField(String value) {
198	        if (value == null) {
199	            return "";
200	        }
201	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
202	    }
203	
204	    Owner toOwner(OwnerDto ownerDto);
205	
206	    @Mapping(target = "id", ignore = true)
207	    @Mapping(target = "pets", ignore = true)
208	    Owner toOwner(OwnerFieldsDto ownerDto);
209	
210	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
211	
212	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
213	
