248	    /**
249	     * Count the members of the new owner's household after this create: the existing owners
250	     * that share the given owner's last name and address (compared case-insensitively with
251	     * collapsed whitespace, the same normalization used to derive the household identifier)
252	     * plus the owner being created. Invoked before the new owner is persisted.
253	     */
254	    private int countHouseholdMembers(Owner owner) {
255	        String normalizedLastName = normalizeHouseholdField(owner.getLastName());
256	        String normalizedAddress = normalizeHouseholdField(owner.getAddress());
257	        long existing = ownerRepository.findAll().stream()
258	            .filter(other -> normalizeHouseholdField(other.getLastName()).equals(normalizedLastName)
259	                && normalizeHouseholdField(other.getAddress()).equals(normalizedAddress))
260	            .count();
261	        return (int) existing + 1;
