278	     * compared case-insensitively. Invoked before the new owner is persisted, so the
279	     * result is the number of namesakes that existed at the time of creation.
280	     */
281	    private int countNamesakes(Owner owner) {
282	        String firstName = owner.getFirstName();
283	        String lastName = owner.getLastName();
284	        if (firstName == null || lastName == null) {
