295	     * the upper-cased first three letters of the owner's city, LAST3 is the upper-cased
296	     * first three letters of the owner's last name and NNNN is a per-city 4-digit
297	     * zero-padded sequence equal to one more than the number of owners already in that city.
298	     */
299	    private String generateCustomerCode(Owner owner) {
300	        String city = owner.getCity();
301	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
302	        String lastName = owner.getLastName();
303	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
304	        int sequence = (int) ownerRepository.findAll().stream()
305	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
306	            .count() + 1;
307	        return String.format("%s-%s-%04d", city3, last3, sequence);
308	    }
